void OrgBackendExternalTest::testParseSimpleTodoHeadline()
{
    const QString orgContent = QStringLiteral("* TODO Buy groceries\n");

    auto items = loadFromOrgContent(orgContent);
    QCOMPARE(items.size(), 1);

    auto inc = items.first();
    QVERIFY(inc->type() == KCalendarCore::Incidence::TypeTodo);
    QCOMPARE(inc->summary(), QStringLiteral("Buy groceries"));

    auto todo = inc.dynamicCast<KCalendarCore::Todo>();
    QVERIFY(todo);
    QVERIFY(!todo->isCompleted());
}

void OrgBackendExternalTest::testParseEventHeadline()
{
    // Headline without TODO keyword is still a Todo (all org headlines are todos)
    const QString orgContent = QStringLiteral(
        "* Meeting with Bob\n"
        "  SCHEDULED: <2024-03-15 Fri 10:00>\n"
    );

    auto items = loadFromOrgContent(orgContent);
    QCOMPARE(items.size(), 1);

    auto inc = items.first();
    QVERIFY(inc->type() == KCalendarCore::Incidence::TypeTodo);
    QCOMPARE(inc->summary(), QStringLiteral("Meeting with Bob"));
}

