void OrgBackendExternalTest::testParseSimpleRepeater()
{
    const QString orgContent = QStringLiteral(
        "* TODO Weekly meeting\n"
        "  SCHEDULED: <2024-01-15 Mon 10:00 +1w>\n"
    );

    auto items = loadFromOrgContent(orgContent);
    QCOMPARE(items.size(), 1);

    auto inc = items.first();
    QVERIFY2(inc->recurs(), "Item with +1w repeater should have recurrence");

    auto recurrence = inc->recurrence();
    QCOMPARE(recurrence->recurrenceType(), static_cast<ushort>(KCalendarCore::Recurrence::rWeekly));
    QCOMPARE(recurrence->frequency(), 1);
}

void OrgBackendExternalTest::testParseCatchUpRepeater()
{
    const QString orgContent = QStringLiteral(
        "* TODO Bill payment\n"
        "  SCHEDULED: <2024-01-15 Mon ++1w>\n"
    );

    auto items = loadFromOrgContent(orgContent);
    QCOMPARE(items.size(), 1);

    auto inc = items.first();
    QVERIFY2(inc->recurs(), "Item with ++1w repeater should have recurrence");

    // Under incidence purity (Feb 2026), repeater syntax is NOT on the incidence.
    // It lives in OrgBackend's private roundtrip data. The incidence just has
    // standard KCalendarCore recurrence (weekly, frequency=1).
    QVERIFY2(inc->customProperty("PLANSTAN", "X-ORG-REPEATER").isEmpty(),
             "Repeater syntax should NOT be on incidence under incidence purity model");
}

void OrgBackendExternalTest::testParseRestartRepeater()
{
    const QString orgContent = QStringLiteral(
        "* TODO Monthly review\n"
        "  SCHEDULED: <2024-01-15 Mon .+1m>\n"
    );

    auto items = loadFromOrgContent(orgContent);
    QCOMPARE(items.size(), 1);

    auto inc = items.first();
    QVERIFY2(inc->recurs(), "Item with .+1m repeater should have recurrence");

    // Under incidence purity (Feb 2026), repeater syntax is NOT on the incidence.
    QVERIFY2(inc->customProperty("PLANSTAN", "X-ORG-REPEATER").isEmpty(),
             "Repeater syntax should NOT be on incidence under incidence purity model");
}

