void OrgBackendExternalTest::testSerializeTodoKeyword()
{
    auto calendar = new KCalendarCore::MemoryCalendar(QTimeZone::utc());

    auto todo = KCalendarCore::Todo::Ptr::create();
    todo->setUid(QStringLiteral("serialize-todo-123"));
    todo->setSummary(QStringLiteral("Test Todo"));
    todo->setStatus(KCalendarCore::Todo::StatusNeedsAction);
    calendar->addTodo(todo);

    QString content = serializeToOrg(calendar, QStringLiteral("serialize-todo-test"));

    QVERIFY2(content.contains(QStringLiteral("TODO")),
             qPrintable(QStringLiteral("Output should contain TODO keyword: ") + content));
    QVERIFY(content.contains(QStringLiteral("Test Todo")));

    delete calendar;
}

