    todo->setPriority(1);
    calendar->addTodo(todo);

    QString content = serializeToOrg(calendar, QStringLiteral("exact-priority-test"));

    QRegularExpression correctOrder(QStringLiteral(R"(^\* TODO \[#A\] Priority Format Test)"),
                                    QRegularExpression::MultilineOption);
    QRegularExpression wrongOrder(QStringLiteral(R"(^\* \[#A\] TODO Priority Format Test)"),
                                  QRegularExpression::MultilineOption);

