void OrgBackendExternalTest::testKeywordRoundtrip()
{
    // WAITING keyword should survive store+reload, not be replaced with INPROGRESS
    const QString orgContent = QStringLiteral(
        "#+TODO: TODO WAITING | DONE DELEGATED\n"
        "* WAITING Needs feedback\n"
        "  :PROPERTIES:\n"
        "  :ID:       kw-roundtrip-123\n"
        "  :END:\n"
    );

    QString calendarId = createOrgFile(orgContent);

    // Load
    OrgBackend backend(m_tempDir->path());
    auto *fetchOp = backend.fetchItems(calendarId);
    QTRY_VERIFY_WITH_TIMEOUT(fetchOp->isFinished(), 5000);
    QCOMPARE(fetchOp->state(), SyncOperation::Succeeded);

    auto fetched = fetchOp->fetchedItems();
    QCOMPARE(fetched.size(), 1);
    auto inc = fetched.first();

    // Store back
    auto *pushOp = backend.pushItems(calendarId, {inc}, TranscodingPlan{});
    QTRY_VERIFY_WITH_TIMEOUT(pushOp->isFinished(), 5000);
    QCOMPARE(pushOp->state(), SyncOperation::Succeeded);

    // Read file and verify WAITING keyword is preserved
    QString filePath = m_tempDir->filePath(calendarId + QStringLiteral(".org"));
    QFile file(filePath);
    QVERIFY(file.open(QIODevice::ReadOnly | QIODevice::Text));
    QString content = QString::fromUtf8(file.readAll());
    file.close();

    QVERIFY2(content.contains(QStringLiteral("WAITING Needs feedback")),
             qPrintable(QStringLiteral("WAITING keyword should survive roundtrip, got:\n") + content));
    QVERIFY2(!content.contains(QStringLiteral("INPROGRESS")),
             qPrintable(QStringLiteral("INPROGRESS should NOT appear (WAITING was the original keyword):\n") + content));
}

// =============================================================================
// BODY CONTENT PRESERVATION (Phase 5)
// =============================================================================

void OrgBackendExternalTest::testSourceBlockSurvivesRoundtrip()
{
    const QString orgContent = QStringLiteral(
        "* TODO Implement feature\n"
        "  :PROPERTIES:\n"
        "  :ID:       src-block-test-1\n"
        "  :END:\n"
        "Some description text\n"
        "#+BEGIN_SRC python\n"
        "def hello():\n"
        "    print(\"world\")\n"
        "#+END_SRC\n"
    );

    QString calendarId = createOrgFile(orgContent);

    OrgBackend backend(m_tempDir->path());
    auto *fetchOp = backend.fetchItems(calendarId);
    QTRY_VERIFY_WITH_TIMEOUT(fetchOp->isFinished(), 5000);
    QCOMPARE(fetchOp->state(), SyncOperation::Succeeded);

    auto fetched = fetchOp->fetchedItems();
    QCOMPARE(fetched.size(), 1);
    auto inc = fetched.first();

    // Description should contain the prose but NOT the source block
    QVERIFY2(inc->description().contains(QStringLiteral("Some description text")),
             qPrintable(QStringLiteral("Description should contain prose: ") + inc->description()));
    QVERIFY2(!inc->description().contains(QStringLiteral("BEGIN_SRC")),
             qPrintable(QStringLiteral("Description should NOT contain source block markers: ") + inc->description()));

    // Store back (description unchanged)
    auto *pushOp = backend.pushItems(calendarId, {inc}, TranscodingPlan{});
    QTRY_VERIFY_WITH_TIMEOUT(pushOp->isFinished(), 5000);
    QCOMPARE(pushOp->state(), SyncOperation::Succeeded);

    // Read file and verify source block survived
    QString filePath = m_tempDir->filePath(calendarId + QStringLiteral(".org"));
    QFile file(filePath);
    QVERIFY(file.open(QIODevice::ReadOnly | QIODevice::Text));
    QString content = QString::fromUtf8(file.readAll());
    file.close();

    QVERIFY2(content.contains(QStringLiteral("#+BEGIN_SRC python")),
             qPrintable(QStringLiteral("Source block BEGIN should survive roundtrip:\n") + content));
    QVERIFY2(content.contains(QStringLiteral("def hello():")),
             qPrintable(QStringLiteral("Source block content should survive roundtrip:\n") + content));
    QVERIFY2(content.contains(QStringLiteral("#+END_SRC")),
             qPrintable(QStringLiteral("Source block END should survive roundtrip:\n") + content));
    QVERIFY2(content.contains(QStringLiteral("Some description text")),
             qPrintable(QStringLiteral("Description prose should survive roundtrip:\n") + content));
}

